#include <bits/stdc++.h>

using namespace std;

const int N = 1e6 + 5;
bool vis[N];
int a[N], n;
vector<int> pos[N * 2];
int solve()
{
	int i, p, ans = 0;
	vector<int> tmp;
	for(i = 1; i < 2 * n; i++)
	{
		if(i & 1)
		{
			p = 0;
			for(auto o: pos[i])
			{
				while(p < pos[i + 1].size() && pos[i + 1][p] < o)
					p++;
				if(p < pos[i + 1].size())
					vis[pos[i + 1][p++]] = 1;
			}
		}
		else
		{
			p = pos[i + 1].size();
			reverse(pos[i].begin(), pos[i].end());
			for(auto o: pos[i])
			{
				while(p && pos[i + 1][p - 1] > o)
					p--;
				if(p)
					vis[pos[i + 1][--p]] = 1;
			}
		}
		tmp.clear();
		for(auto o: pos[i + 1])
			if(vis[o])
				ans++;
			else
				tmp.emplace_back(o);
		pos[i + 1] = tmp;
	}
	return ans;
}

int main()
{
	int t, i, ans;
	scanf("%d", &t);
	while(t--)
	{
		scanf("%d", &n);
		for(i = 1; i <= n; i++)
			scanf("%d", a + i);
		for(i = 1; i <= n; i++)
			vis[i] = 0;
		for(i = 1; i <= 2 * n; i++)
			pos[i].clear();
		for(i = 1; i <= n; i++)
			pos[a[i]].emplace_back(i);
		ans = n - solve();
		reverse(a + 1, a + n + 1);
		for(i = 1; i <= n; i++)
			vis[i] = 0;
		for(i = 1; i <= 2 * n; i++)
			pos[i].clear();
		for(i = 1; i <= n; i++)
			pos[a[i]].emplace_back(i);
		ans -= solve();
		printf("%d\n", ans);
	}
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 1e6 + 5, inf = 1e9;
int a[N], lp[N], rp[N], Lp[N], m;
vector<int> pos[N * 2], dp[N * 2], tmp;
int solve()
{
	int i, j, u, v, p;
	dp[1].resize(pos[1].size());
	for(i = 0; i < pos[1].size(); i++)
		dp[1][i] = i;
	for(i = 1; i < m; i += 2)
	{
		u = pos[i].size() - 1;
		v = pos[i + 2].size() - 1;
		tmp.clear();
		tmp.resize(u + 1);
		dp[i + 2].clear();
		dp[i + 2].resize(v + 1);
		for(j = 0; j <= u; j++)
			tmp[j] = dp[i][j] - rp[pos[i][j]];
		for(j = u; j > 0; j--)
			tmp[j - 1] = max(tmp[j - 1], tmp[j]);
		for(j = 0; j <= v; j++)
		{
			p = pos[i + 2][j];
			if(j)
				dp[i + 2][j] = dp[i + 2][j - 1];
			if(Lp[p] < u)
				dp[i + 2][j] = max(dp[i + 2][j], j + tmp[Lp[p] + 1]);
			dp[i + 2][j] = max(dp[i + 2][j], j - lp[p] + dp[i][Lp[p]]);
		}
	}
	return dp[m].back();
}

int main()
{
