			m = max(m, a[i]);
			ans -= 2 * (a[i] & 1);
		}
		m |= 1;
		for(i = 1; i <= m; i++)
			pos[i] = {0};
		for(i = 1; i <= n; i++)
		{
			pos[a[i]].emplace_back(i);
			lp[i] = (a[i] > 1 ? pos[a[i] - 1].size() - 1 : 0);
			rp[i] = (a[i] < m ? pos[a[i] + 1].size() - 1 : 0);
			Lp[i] = (a[i] > 2 ? pos[a[i] - 2].size() - 1 : 0);
		}
		ans += solve();
		reverse(a + 1, a + n + 1);
		for(i = 1; i <= m; i++)
			pos[i] = {0};
		for(i = 1; i <= n; i++)
		{
			pos[a[i]].emplace_back(i);
			lp[i] = (a[i] > 1 ? pos[a[i] - 1].size() - 1 : 0);
			rp[i] = (a[i] < m ? pos[a[i] + 1].size() - 1 : 0);
			Lp[i] = (a[i] > 2 ? pos[a[i] - 2].size() - 1 : 0);
		}
		ans += solve();
		printf("%d\n", ans);
	}
