}

#include <bits/stdc++.h>

using namespace std;

const int N = 3e5 + 5;
vector<int> e[N];
int val[N], cnt[N], deg[N], h[N], d;
queue<int> q;
int del(int x)
{
	cnt[deg[x]]--;
	cnt[--deg[x]]++;
	return deg[x];
}

int main()
{
	int t, n, i, u, v, k, c;
	scanf("%d", &t);
	while(t--)
	{
		scanf("%d", &n);
		for(i = 1; i <= n; i++)
			e[i].clear();
		for(i = 1; i < n; i++)
		{
			scanf("%d%d", &u, &v);
			e[u].emplace_back(v);
			e[v].emplace_back(u);
		}
		for(i = 0; i <= n; i++)
		{
			val[i] = 1e9;
			cnt[i] = 0;
			h[i] = 1;
		}
		for(i = 1; i <= n; i++)
			cnt[deg[i] = e[i].size()]++;
		for(i = 1; i <= n; i++)
			if(deg[i] == 1)
				q.push(i);
		c = 0;
		d = n;
		while(!cnt[d])
			d--;
		val[1] = min(val[1], 1);
		val[d] = min(val[d], 2);
		while(!q.empty())
		{
			k = q.front();
			q.pop();
			for(auto o: e[k])
				if(del(o) == 1)
				{
					h[o] = h[k] + 1;
					q.push(o);
				}
			++c;
			while(!cnt[d])
				d--;
			val[c + 1] = min(val[c + 1], 2 * h[k] + 1);
			val[c + d] = min(val[c + d], 2 * h[k] + 2);
		}
		for(i = n - 1; i >= 1; i--)
			val[i] = min(val[i], val[i + 1]);
		for(i = 1; i < n; i++)
			printf("%d ", val[i]);
		printf("\n");
	}
	return 0;
}

#include <bits/stdc++.h>
#define N 1000011
using namespace std;
int T,n,a[N],id[N];
int R[N];
struct sgt
{
	int D,mx[N*4];
	int query(int l,int r)
	{
		l+=D-1;r+=D+1;int ans=0;
		while(l^r^1)
		{
			if(!(l&1))ans=max(ans,mx[l^1]);
			if(r&1)ans=max(ans,mx[r^1]);
			l>>=1;r>>=1;
		}
		return ans;
	}
	void modi(int k,int p)
	{
		k+=D;mx[k]=p;
		while(k>>=1)mx[k]=max(mx[k<<1],mx[k<<1|1]);
	}
	void clear()
	{
		D=1;while(D<=n+10)D<<=1;
		for(int i=0;i<D+D;++i)mx[i]=0;
	}
}T1,T2;
int pl[N],res[N],curr[N];
int Rmn[N];
void proc()
{
	for(int i=1;i<=n;++i)R[i]=Rmn[i]=i+1,id[a[i]]=i,pl[i]=0;
	for(int i=n;i;--i)while(R[i]<=n&&a[R[i]]<a[i])R[i]=R[R[i]];
	for(int i=n;i;--i)while(Rmn[i]<=n&&a[Rmn[i]]>a[i])Rmn[i]=Rmn[Rmn[i]];
	T1.clear();
	for(int i=1;i<=n;++i)
	{
		if(R[i]<=n)
		{
			int k=T1.query(a[i]+1,a[R[i]]-1);
			pl[i]=k;
		}
		T1.modi(a[i],i);
	}
	T2.clear();
	for(int i=1;i<=n;++i)curr[i]=res[i]=0;
	for(int i=n;i;--i)
	{
		int x=id[i],y=Rmn[x];
		if(y<=n)
		{
			int rr=n+1-T2.query(y+1,n);
			if(rr<=n)res[rr]=max(res[rr],x);
		}
		if(pl[x])T2.modi(pl[x],curr[pl[x]]=max(curr[pl[x]],n+1-R[x]));
	}
	for(int i=1;i<=n;++i)res[i]=max(res[i],res[i-1]);
}
int main()
{
	scanf("%d",&T);while(T--)
	{
		scanf("%d",&n);
		for(int i=1;i<=n;++i)scanf("%d",a+i);
		proc();
		long long ans=0;
		for(int i=1;i<=n;++i)ans+=res[i];
		printf("%lld\n",ans);
	}
}
